// All --zimm-* variables with fully-resolved literal values (no var() chains).
// Injected onto :root by _app-config/index.tsx via <Global> from @emotion/react, so the
// .zimm-* classes in globalStyles.ts can resolve their var(--zimm-*) references.
import { FONT_MEDIUM, FONT_REGULAR, FONT_SERIF } from './fonts';
export const zimmTokens: Record<string, string> = {
  // ---- Brand / Primitive: Greys ----
  '--zimm-color-grey-black': 'black',
  '--zimm-color-grey-900': '#191919',
  '--zimm-color-grey-800': '#282828',
  '--zimm-color-grey-700': '#454545',
  '--zimm-color-grey-600': '#666',
  '--zimm-color-grey-500': '#707070',
  '--zimm-color-grey-300': '#969696',
  '--zimm-color-grey-200': '#d1d1d1',
  '--zimm-color-grey-100': '#e6e6e6',
  '--zimm-color-grey-white': 'white',

  // ---- Brand / Primitive: Ivory ----
  '--zimm-color-ivory-400': '#f2e9e0',
  '--zimm-color-ivory-300': '#fbf5ef',
  '--zimm-color-ivory-200': '#f6f4f1',
  '--zimm-color-ivory-100': '#f9f8f6',

  // ---- Brand / Primitive: Status ----
  '--zimm-color-coral-500': '#f98f8c',
  '--zimm-color-green-500': '#2d5a3d',
  '--zimm-color-orange-500': '#d67600',
  '--zimm-color-red-500': '#9c0000',

  // ---- Brand / Primitive: Opacity (base: grey/900 #191919) ----
  '--zimm-color-opacity-50': 'rgba(25, 25, 25, 0.50)',
  '--zimm-color-opacity-40': 'rgba(25, 25, 25, 0.40)',
  '--zimm-color-opacity-30': 'rgba(25, 25, 25, 0.30)',
  '--zimm-color-opacity-15': 'rgba(25, 25, 25, 0.15)',

  // ---- Alias / Semantic: Text ----
  '--zimm-color-text-default': '#191919',
  '--zimm-color-text-inverse': 'white',
  '--zimm-color-text-inverse-grey': '#969696',
  '--zimm-color-text-secondary': '#666',
  '--zimm-color-text-muted': '#969696',

  // ---- Alias / Semantic: Background ----
  '--zimm-color-bg-01': '#f9f8f6',
  '--zimm-color-bg-02': '#f6f4f1',
  '--zimm-color-bg-03': '#fbf5ef',
  '--zimm-color-bg-04': '#f2e9e0',
  '--zimm-color-bg-05': '#191919',
  '--zimm-color-bg-06': '#282828',
  '--zimm-color-bg-07': 'white',

  // ---- Alias / Semantic: Border ----
  '--zimm-color-border-default': '#e6e6e6',
  '--zimm-color-border-secondary': '#d1d1d1',
  '--zimm-color-border-focus': '#191919',
  '--zimm-color-border-forms': '#707070',

  // ---- Composite: Focus ring ----
  '--zimm-focus-ring': '1px solid #191919',

  // ---- Alias / Semantic: Status ----
  '--zimm-color-status-success': '#2d5a3d',
  '--zimm-color-status-error': '#9c0000',
  '--zimm-color-status-error-bg': '#f98f8c',
  '--zimm-color-status-store-closed': '#d67600',

  // ---- Alias / Semantic: Link ----
  '--zimm-color-link-default': '#191919',
  '--zimm-color-link-hover': '#707070',

########## motion.ts (NEW) ##########
// Motion tokens — source: Zimmermann Design System 2026 (Handover common.css)
// PROVISIONAL: Motion design is pending formal sign-off. Values are functional
// placeholders used in prototypes. Do not treat as final — confirm with the UI
// designer against the Handover design system before relying on them.
export const motion = {
  duration: {
    fast: '200ms',
    default: '300ms',
    slow: '500ms',
  },
  easing: {
    // General-purpose default
    standard: 'ease',
    // Luxury deceleration — panels and overlays entering the screen (from common.css)
    slides: 'cubic-bezier(0.87, 0, 0.13, 1)',
    // Fades (from common.css)
    fades: 'cubic-bezier(0.37, 0, 0.63, 1)',
  },
} as const;

########## sizes.ts (NEW) ##########
// Icon sizes — source: Zimmermann Design System 2026 (Handover tokens.md § Icon Sizes)
//
// Deliberately NOT registered as `theme.sizes`. Chakra's `sizes.lg` is 32rem and
// backs every `w`/`h`/`boxSize` token across the base retail-react-app, so
// remapping these names would resize base components. Import these constants
// directly instead — the same pattern component overrides already use for
// FONT_MEDIUM: `<Icon boxSize={iconSizes.lg} />`.
export const iconSizes = {
  lg: '20px',
  md: '16px',
  sm: '12px',
} as const;

// Action (button) sizing — source: Handover tokens/spacing.css (--zimm-size-action-*).
// The CSS-var twins already exist in zimmTokens.ts and back the .zimm-btn-* global
// classes; these are the TypeScript equivalents for Chakra component overrides, so
// button dimensions stop being hardcoded in theme/components/button.ts.
export const actionSizes = {
  height: {
    lg: '52px',
    md: '40px',
  },
  paddingX: {
    lg: '32px',
    md: '20px',
  },
  gap: '16px',
} as const;

