@@ -14,16 +14,51 @@
  */
 import baseTheme from '@salesforce/retail-react-app/app/theme';
 import { extendTheme, type ThemeOverride } from '@chakra-ui/react';
-import { breakpoints, colors, fonts, spacing, textStyles } from './foundation';
+import { borderWidths, breakpoints, colors, fonts, spacing, textStyles } from './foundation';
 import { components } from './components';
+import { globalStyles } from './globalStyles';
+
+// Note: --zimm-* CSS custom properties are injected onto :root via a raw
+// <Global> in _app-config/index.tsx (ZimmTokensGlobal). They cannot go through
+// Chakra's styles.global because Chakra's style processor strips quotes from
+// font-family values like "'Futura Round', sans-serif", outputting just "sans-serif".
+//
+// ---------------------------------------------------------------------------
+// Which foundations are registered as Chakra scales, and which are not
+// ---------------------------------------------------------------------------
+// Registered below: borderWidths, breakpoints, colors, fonts, space, textStyles.
+//
+// Deliberately NOT registered, because the Zimmermann scale and the Chakra scale
+// use the same key names for different values — remapping them would silently
+// restyle the base retail-react-app, which uses those names at ~199 call sites:
+//
+//   fontSizes    Chakra md=16px xs=12px 2xs=10px 3xs=7.2px
+//                Zimmermann md=24px xs=16px 2xs=14px 3xs=12px  (4 collisions)
+//   transition   Chakra duration.fast=150ms slow=300ms
+//                Zimmermann fast=200ms default=300ms slow=500ms
+//   sizes        Chakra sizes.lg=32rem vs iconSizes.lg=20px
+//
+// Set type with `textStyle` (all 22 Handover text styles are registered), never a
+// raw `fontSize` token. For motion, icon and action dimensions, import the
+// constants from `foundation/` directly — the pattern component overrides already
+// use for FONT_MEDIUM. `theme/index.test.tsx` guards these scales against being
+// remapped by a future change.
+//
+// The 15 numeric `--zimm-scale-NNN` aliases are duplicates of the named scale
+// (400 = 16px = `m`) and exist only for the .zimm-* global classes; the named
+// scale is the Chakra-facing surface.

 const overrides: ThemeOverride = {
+  borderWidths,
   breakpoints,
   colors,
   fonts,
   space: spacing,
   textStyles,
   components,
+  styles: {
+    global: globalStyles,
+  },
 };

 const theme = extendTheme(baseTheme, overrides);

