 import { ChakraProvider } from '@salesforce/retail-react-app/app/components/shared/ui';
+import { getAssetUrl } from '@salesforce/pwa-kit-react-sdk/ssr/universal/utils';
+import { zimmTokens } from '../../theme/foundation/zimmTokens';

 // Removes focus for non-keyboard interactions for the whole application
 import 'focus-visible/dist/focus-visible';

 import theme from '../../theme';
+
+// Inject --zimm-* tokens as raw CSS onto :root via Emotion, bypassing Chakra's
+// style processor which strips quotes from font-family values.
+const zimmRootVarsCss = css`
+  :root {
