+      .map(([k, v]) => `${k}:${v}`)
+      .join(';')}
+  }
+`;
 import { MultiSiteProvider, StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts';
 import {
   resolveSiteFromUrl,
@@ -91,6 +105,113 @@ type AppConfigProps = {
   locals?: AppLocals;
 };

+// Preload the only two Futura Round faces the type scale actually uses (400 regular,
+// 500 medium).
+//
+// Emotion 11 inserts <style data-emotion="css-global"> tags inline during
+// ReactDOMServer.renderToString (which is what pwa-kit-react-sdk's
+// ssr/server/react-rendering.js uses), so the @font-face rules below ARE present in
+// the server-rendered HTML without @emotion/server — verified 2026-08-12. They land
+// in <body> where the <Global> sits in the tree, though, not in <head>: the browser
+// only discovers them partway through parsing, so the font fetch starts later than it
+// needs to. This preload moves that discovery into <head> so the fetch begins with
+// the document.
+//
+// Helmet is the only supported route into <head> here: _document lives in
+// pwa-kit-react-sdk (outside the overrides mechanism) and React 18 does not hoist
+// <link> elements.
+function FuturaFontPreload() {
+  const b = (name: string) => getAssetUrl(`static/fonts/${name}`);
+  return (
+    <Helmet>
+      <link rel="preload" as="font" type="font/woff2" crossOrigin="anonymous" href={b('FuturaRound-Regular.woff2')} />
+      <link rel="preload" as="font" type="font/woff2" crossOrigin="anonymous" href={b('FuturaRound-Medium.woff2')} />
+    </Helmet>
+  );
+}
+
+// Futura Round @font-face — built at render time so getAssetUrl can access
+// window.Progressive.buildOrigin (not available at module evaluation time).
+function FuturaFontFaces() {
+  const b = (name: string) => getAssetUrl(`static/fonts/${name}`);
+  return (
+    <Global
+      styles={css`
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-Regular.woff2')}') format('woff2');
+          font-weight: 400;
+          font-style: normal;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-Oblique.woff2')}') format('woff2');
+          font-weight: 400;
+          font-style: italic;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-Light.woff2')}') format('woff2');
+          font-weight: 300;
+          font-style: normal;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-LightOblique.woff2')}') format('woff2');
+          font-weight: 300;
+          font-style: italic;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-Medium.woff2')}') format('woff2');
+          font-weight: 500;
+          font-style: normal;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-MediumOblique.woff2')}') format('woff2');
+          font-weight: 500;
+          font-style: italic;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-Demi.woff2')}') format('woff2');
+          font-weight: 600;
+          font-style: normal;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-DemiOblique.woff2')}') format('woff2');
+          font-weight: 600;
+          font-style: italic;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-Bold.woff2')}') format('woff2');
+          font-weight: 700;
+          font-style: normal;
+          font-display: swap;
+        }
+        @font-face {
+          font-family: 'Futura Round';
+          src: url('${b('FuturaRound-BoldOblique.woff2')}') format('woff2');
+          font-weight: 700;
+          font-style: italic;
+          font-display: swap;
+        }
+      `}
+    />
+  );
+}
+
 /**
  * Use the AppConfig component to inject extra arguments into the getProps
  * methods for all Route Components in the app – typically you'd want to do this
@@ -152,7 +273,12 @@ const AppConfig = ({ children, locals = {} }: AppConfigProps): React.ReactElemen
       <MultiSiteProvider site={locals.site} locale={locals.locale} buildUrl={locals.buildUrl}>
         <StoreLocatorProvider config={storeLocatorConfig}>
           <ContentfulLivePreviewProvider locale={locale} enableInspectorMode enableLiveUpdates>
-            <ChakraProvider theme={theme}>{children}</ChakraProvider>
+            <ChakraProvider theme={theme}>
+              <Global styles={zimmRootVarsCss} />
+              <FuturaFontPreload />
+              <FuturaFontFaces />
+              {children}
+            </ChakraProvider>
           </ContentfulLivePreviewProvider>
         </StoreLocatorProvider>
       </MultiSiteProvider>

